import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"Plugin API","description":"Standalone API setup, lifecycle, host interfaces, ABI support and migration","frontmatter":{"navigation":{"category":"Plugin API"},"title":"Plugin API","description":"Standalone API setup, lifecycle, host interfaces, ABI support and migration","editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/plugin-api/index.md"},"headers":[],"relativePath":"docs/plugin-api/index.md","filePath":"docs/plugin-api/index.md","lastUpdated":1792252051000}`),a={name:`docs/plugin-api/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plugin-api" tabindex="-1">Plugin API <a class="header-anchor" href="#plugin-api" aria-label="Permalink to “Plugin API”">​</a></h1><p>Use <code>@pumpkin-plugins/pumpkin-api</code> as the runtime API in a standalone TypeScript plugin. Once both packages are published to npm, install the API and build tool:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/pumpkin-api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @pumpkin-plugins/build</span></span></code></pre></div><p>Start with the guide that matches what you need to do:</p><ul><li><a href="/pumpkin-plugins/docs/plugin-api/setup-and-build">Set up and build a plugin</a>: configure the package, generate WIT declarations and build the component.</li><li><a href="/pumpkin-plugins/docs/plugin-api/lifecycle-and-registration">Register lifecycle hooks and handlers</a>: implement startup and shutdown behavior and register callbacks.</li><li><a href="/pumpkin-plugins/docs/plugin-api/host-api">Find a host operation</a>: browse the Pumpkin WIT interface areas and understand how they differ from WASI capabilities.</li><li><a href="/pumpkin-plugins/docs/plugin-api/abi-and-runtime">Check ABI and runtime support</a>: match the host ABI to your Pumpkin server and check engine-specific limits.</li><li><a href="/pumpkin-plugins/docs/plugin-api/api-evolution-and-migration">Review compatibility or migrate</a>: understand API versioning and move from <code>@pumpkinmc/pumpkin-api-ts</code>.</li><li><a href="/pumpkin-plugins/api/tools/@pumpkin-plugins/pumpkin-api/">Browse the generated API reference</a>: look up exported symbols and their JSDoc.</li></ul><p>The npm version of <code>@pumpkin-plugins/pumpkin-api</code> and the Pumpkin host ABI version are separate. Check the <a href="/pumpkin-plugins/docs/plugin-api/abi-and-runtime">ABI and runtime guide</a> when choosing a server release; generated TypeScript declarations alone don&#39;t confirm that the server or selected engine supports an operation.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};